-- ════════════════════════════════════════════════════════════════════
-- MotoGo24 — SEED doporučených tras — FRANCIE (10 tras)
-- NEAPLIKOVÁNO na živou DB — přehled a spuštění je na adminovi.
-- Trasy: is_active=false (Skryto) + status='approved' → ve Velíně zkontroluj a Publikuj.
-- Idempotence: každá trasa se před vložením smaže dle (name, branch_id).
-- ════════════════════════════════════════════════════════════════════
alter table public.routes add column if not exists countries text[] not null default '{}'::text[];

do $$
declare
  v_branch uuid;
  v_route  uuid;
begin
  -- Domovská pobočka = nejbližší k Mezné (49.3464, 15.2119); fallback první.
  select id into v_branch from public.branches
    order by (power(coalesce(gps_lat,0)-49.3464,2) + power(coalesce(gps_lng,0)-15.2119,2)) asc
    limit 1;
  if v_branch is null then
    raise exception 'Nenalezena žádná pobočka v public.branches — nelze nasadit trasy.';
  end if;

  -- Vogézy – Route des Crêtes a Grand Ballon
  delete from public.routes where name = 'Vogézy – Route des Crêtes a Grand Ballon' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Vogézy – Route des Crêtes a Grand Ballon', 'Legendární hřebenová silnice Route des Crêtes vznikla za první světové války jako zásobovací trasa a dnes je to jedna z nejlepších motorkářských silnic východní Francie. Okruh z Munsteru střídá stovky plynulých zatáček v bukových a smrkových lesích s otevřenými pastvinami na hřebeni, odkud dohlédnete přes rýnskou nížinu až k Alpám. Vrcholem je výjezd na Grand Ballon (1424 m), nejvyšší horu Vogéz, a pietní zastávka na bojišti Hartmannswillerkopf. Povrch je vesměs výborný, ideální sezóna od května do října; nejvyšší úseky bývají v zimě uzavřené. O letních víkendech počítejte s cyklisty a pomalejšími auty, na hřebeni se rychle mění počasí a padají mlhy.', 'loop', 140, 240, 'medium',
     '[{"lat": 48.0406, "lng": 7.1390, "label": "Start: Munster"}, {"lat": 48.1367, "lng": 7.0908, "label": "Lac Blanc"}, {"lat": 48.0633, "lng": 7.0225, "label": "Col de la Schlucht"}, {"lat": 48.0403, "lng": 7.0161, "label": "Hohneck"}, {"lat": 47.9011, "lng": 7.0839, "label": "Grand Ballon"}, {"lat": 47.8558, "lng": 7.1594, "label": "Hartmannswillerkopf"}, {"lat": 48.0406, "lng": 7.1390, "label": "Cíl: Munster"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=48.0406,7.1390&destination=48.0406,7.1390&travelmode=driving&waypoints=48.1367,7.0908%7C48.0633,7.0225%7C48.0403,7.0161%7C47.9011,7.0839%7C47.8558,7.1594', 'https://commons.wikimedia.org/wiki/Special:FilePath/Lac%20Blanc%20Vosges.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Lac%20Blanc%20Vosges.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Col%20de%20la%20Schlucht.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Le%20Hohneck.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Grand%20Ballon.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Hartmannswillerkopf.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Munster%20(Haut-Rhin).jpg"}'::text[], '{"Lac Blanc","Col de la Schlucht","Hohneck","Grand Ballon","Hartmannswillerkopf (Vieil Armand)","Restaurace: Hôtel Verte Vallée (Munster)"}'::text[], '{"FR"}'::text[], false, 3810, 'approved');

  -- Alsaská vinná stezka – Riquewihr a Haut-Kœnigsbourg
  delete from public.routes where name = 'Alsaská vinná stezka – Riquewihr a Haut-Kœnigsbourg' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Alsaská vinná stezka – Riquewihr a Haut-Kœnigsbourg', 'Pohodová vyjížďka po slavné Route des Vins d''Alsace, která se vine úpatím Vogéz mezi nekonečnými vinicemi ryzlinku a gewürztraminentu. Okruh z Colmaru navléká jako korálky nejkrásnější hrázděná městečka Francie — Eguisheim, Kaysersberg, Riquewihr a Ribeauvillé — a vrcholí výjezdem serpentinami k mohutnému hradu Haut-Kœnigsbourg. Silnice jsou úzké, ale kvalitní, provoz mimo sezónu klidný; jde spíš o požitkářskou jízdu s častými zastávkami než o sportovní svezení. Nejhezčí je pozdní léto a vinobraní v září a říjnu, kdy vinice zezlátnou. O víkendech počítejte s turisty v uličkách a plnými parkovišti u městeček.', 'loop', 95, 180, 'easy',
     '[{"lat": 48.0778, "lng": 7.3556, "label": "Start: Colmar"}, {"lat": 48.0428, "lng": 7.3062, "label": "Eguisheim"}, {"lat": 48.1392, "lng": 7.2617, "label": "Kaysersberg"}, {"lat": 48.1667, "lng": 7.2986, "label": "Riquewihr"}, {"lat": 48.1953, "lng": 7.3196, "label": "Ribeauvillé"}, {"lat": 48.2494, "lng": 7.3444, "label": "Château du Haut-Kœnigsbourg"}, {"lat": 48.0778, "lng": 7.3556, "label": "Cíl: Colmar"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=48.0778,7.3556&destination=48.0778,7.3556&travelmode=driving&waypoints=48.0428,7.3062%7C48.1392,7.2617%7C48.1667,7.2986%7C48.1953,7.3196%7C48.2494,7.3444', 'https://commons.wikimedia.org/wiki/Special:FilePath/Eguisheim.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Eguisheim.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Kaysersberg.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Riquewihr.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Riquewihr.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Ribeauvill%C3%A9.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Haut-Koenigsbourg.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Colmar%20Petite%20Venise.jpg"}'::text[], '{"Eguisheim","Kaysersberg","Riquewihr","Restaurace: La Table du Gourmet (Riquewihr)","Ribeauvillé","Château du Haut-Kœnigsbourg","Colmar – Petite Venise"}'::text[], '{"FR"}'::text[], false, 3820, 'approved');

  -- Provence – Mont Ventoux a vesnice Luberonu
  delete from public.routes where name = 'Provence – Mont Ventoux a vesnice Luberonu' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Provence – Mont Ventoux a vesnice Luberonu', 'Okruh srdcem Provence spojuje dvě tváře kraje: holý vápencový obr Mont Ventoux (1910 m) s legendárním stoupáním z Bédoin a malebné vesnice Luberonu posazené na skalách nad levandulovými poli. Z vrcholu Ventoux, kde to při mistralu pořádně fouká, sjedete přes levandulové plošiny u Sault do kraje okrových skal Roussillonu a kamenného Gordes. Silnice jsou úzké, zatáčkovité a v létě rozpálené — jeďte brzy ráno, kdy je Ventoux bez aut a levandule nejvoňavější. Nejlepší termín je konec června a červenec, kdy kvete levandule; vrchol Ventoux bývá otevřený zhruba od května do listopadu. Pozor na cyklisty, kterých na Ventoux potkáte stovky, a na štěrk v serpentinách nad hranicí lesa.', 'loop', 165, 280, 'medium',
     '[{"lat": 44.0556, "lng": 5.0489, "label": "Start: Carpentras"}, {"lat": 44.1244, "lng": 5.1797, "label": "Bédoin"}, {"lat": 44.1741, "lng": 5.2786, "label": "Mont Ventoux"}, {"lat": 44.0894, "lng": 5.4103, "label": "Sault"}, {"lat": 43.9028, "lng": 5.2928, "label": "Roussillon"}, {"lat": 43.9114, "lng": 5.2003, "label": "Gordes"}, {"lat": 43.9231, "lng": 5.1272, "label": "Fontaine-de-Vaucluse"}, {"lat": 44.0556, "lng": 5.0489, "label": "Cíl: Carpentras"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=44.0556,5.0489&destination=44.0556,5.0489&travelmode=driving&waypoints=44.1244,5.1797%7C44.1741,5.2786%7C44.0894,5.4103%7C43.9028,5.2928%7C43.9114,5.2003%7C43.9231,5.1272', 'https://commons.wikimedia.org/wiki/Special:FilePath/MontVentoux.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/MontVentoux.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Sault%20Vaucluse.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Roussillon%20Vaucluse.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Gordes.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Abbaye%20de%20S%C3%A9nanque.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Fontaine-de-Vaucluse.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Carpentras.jpg"}'::text[], '{"Mont Ventoux","Sault – levandulová pole","Roussillon – okrové skály","Gordes","Abbaye de Sénanque","Fontaine-de-Vaucluse","Restaurace: Chez Serge (Carpentras)"}'::text[], '{"FR"}'::text[], false, 3830, 'approved');

  -- Ardèche – kaňon řeky a Pont d'Arc
  delete from public.routes where name = 'Ardèche – kaňon řeky a Pont d''Arc' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Ardèche – kaňon řeky a Pont d''Arc', 'Vyhlídková silnice D290 nad kaňonem Gorges de l''Ardèche je jedna z nejefektnějších jízd jižní Francie — 30 km zatáček po hraně vápencové soutěsky s tuctem vyhlídek vysoko nad smaragdovou řekou plnou kánoí. Okruh z Vallon-Pont-d''Arc začíná u slavného skalního oblouku Pont d''Arc, pokračuje po korniši ke všem belvedérům a vrací se přes jeskynní systém Aven d''Orgnac a středověké vesničky Labeaume, Balazuc a Vogüé v údolí řeky. Povrch je dobrý, ale v létě tu bývá hustý turistický provoz a rozpálený asfalt — nejlépe se jede květen, červen a září. Ráno po ránu bývají v kaňonu mlhy a na korniši zvěř. U vyhlídek parkujte jen na značených místech, odtahy tu fungují spolehlivě.', 'loop', 120, 210, 'medium',
     '[{"lat": 44.4067, "lng": 4.3928, "label": "Start: Vallon-Pont-d''Arc"}, {"lat": 44.3803, "lng": 4.4122, "label": "Pont d''Arc"}, {"lat": 44.3390, "lng": 4.5160, "label": "Belvédère de la Madeleine"}, {"lat": 44.3186, "lng": 4.4108, "label": "Aven d''Orgnac"}, {"lat": 44.5083, "lng": 4.3711, "label": "Balazuc"}, {"lat": 44.5386, "lng": 4.4144, "label": "Vogüé"}, {"lat": 44.4067, "lng": 4.3928, "label": "Cíl: Vallon-Pont-d''Arc"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=44.4067,4.3928&destination=44.4067,4.3928&travelmode=driving&waypoints=44.3803,4.4122%7C44.3390,4.5160%7C44.3186,4.4108%7C44.5083,4.3711%7C44.5386,4.4144', 'https://commons.wikimedia.org/wiki/Special:FilePath/Pont%20d%27Arc.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Pont%20d%27Arc.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Gorges%20de%20l%27Ard%C3%A8che.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Aven%20d%27Orgnac.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Labeaume.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Balazuc.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Vog%C3%BC%C3%A9.jpg"}'::text[], '{"Pont d''Arc","Belvédère de la Madeleine (Gorges de l''Ardèche)","Aven d''Orgnac","Labeaume","Balazuc","Vogüé"}'::text[], '{"FR"}'::text[], false, 3840, 'approved');

  -- Auvergne – kraj vyhaslých sopek
  delete from public.routes where name = 'Auvergne – kraj vyhaslých sopek' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Auvergne – kraj vyhaslých sopek', 'Okruh největším sopečným polem Evropy — Chaîne des Puys u Clermont-Ferrand je od roku 2018 na seznamu UNESCO a z motorky vypadá jako krajina z jiné planety: desítky pravidelných zelených kuželů, kráterová jezera a horské pastviny. Trasa vede prázdnými silnicemi přes úpatí Puy de Dôme, kolem jezera Guéry do lázeňského Le Mont-Dore pod nejvyšší horou Massif Central Puy de Sancy a zpět přes kráterové jezero Pavin a středověké Besse. Provoz je i v sezóně minimální, asfalt slušný a zatáček nekonečno; ideální období je květen až říjen. Počítejte s rychlými změnami počasí — Sancy umí i v létě zatáhnout a zchladit pod deset stupňů. Na pastvinách se volně pohybují krávy salers, v zatáčkách přes hřebeny jezděte s rezervou.', 'loop', 150, 240, 'medium',
     '[{"lat": 45.7772, "lng": 3.0870, "label": "Start: Clermont-Ferrand"}, {"lat": 45.7961, "lng": 2.9700, "label": "Puy de Pariou"}, {"lat": 45.7722, "lng": 2.9644, "label": "Puy de Dôme"}, {"lat": 45.6083, "lng": 2.8092, "label": "Lac de Guéry"}, {"lat": 45.5714, "lng": 2.8083, "label": "Le Mont-Dore"}, {"lat": 45.4956, "lng": 2.8878, "label": "Lac Pavin"}, {"lat": 45.5178, "lng": 2.9331, "label": "Besse-et-Saint-Anastaise"}, {"lat": 45.7772, "lng": 3.0870, "label": "Cíl: Clermont-Ferrand"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=45.7772,3.0870&destination=45.7772,3.0870&travelmode=driving&waypoints=45.7961,2.9700%7C45.7722,2.9644%7C45.6083,2.8092%7C45.5714,2.8083%7C45.4956,2.8878%7C45.5178,2.9331', 'https://commons.wikimedia.org/wiki/Special:FilePath/Puy%20de%20D%C3%B4me.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Puy%20de%20D%C3%B4me.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Puy%20Pariou.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Lac%20de%20Gu%C3%A9ry.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Puy%20de%20Sancy.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Le%20Mont-Dore.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Lac%20Pavin.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Besse-et-Saint-Anastaise.jpg"}'::text[], '{"Puy de Dôme","Puy de Pariou","Lac de Guéry","Puy de Sancy","Restaurace: Le Bougnat (Le Mont-Dore)","Lac Pavin","Besse-et-Saint-Anastaise"}'::text[], '{"FR"}'::text[], false, 3850, 'approved');

  -- Pyreneje – Col du Tourmalet a Pic du Midi
  delete from public.routes where name = 'Pyreneje – Col du Tourmalet a Pic du Midi' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Pyreneje – Col du Tourmalet a Pic du Midi', 'Okruh přes dva legendární pyrenejské průsmyky Tour de France — Col du Tourmalet (2115 m), nejvyšší silniční sedlo francouzských Pyrenejí, a zelený Col d''Aspin (1490 m). Z poutního města Lourdes stoupáte soutěskou do Luz-Saint-Sauveur a pak devatenácti kilometry serpentin na Tourmalet, kde vás přivítá socha obřího cyklisty a výhled na observatoř Pic du Midi. Sjezd přes lyžařskou La Mongie střídá pastviny s volně pobíhajícími ovcemi, lamami a kravami — brzděte s předstihem. Průsmyky jsou průjezdné zhruba od června do října, mimo tento čas hrozí sníh; nejlepší je září, kdy zmizí karavany. Náročnější trasa odmění jezdce jedním z nejkrásnějších vysokohorských dnů ve Francii.', 'loop', 165, 270, 'hard',
     '[{"lat": 43.0983, "lng": -0.0508, "label": "Start: Lourdes"}, {"lat": 42.8722, "lng": 0.0011, "label": "Luz-Saint-Sauveur"}, {"lat": 42.9083, "lng": 0.1450, "label": "Col du Tourmalet"}, {"lat": 42.9394, "lng": 0.3258, "label": "Col d''Aspin"}, {"lat": 42.9047, "lng": 0.3592, "label": "Arreau"}, {"lat": 43.0647, "lng": 0.1497, "label": "Bagnères-de-Bigorre"}, {"lat": 43.0983, "lng": -0.0508, "label": "Cíl: Lourdes"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=43.0983,-0.0508&destination=43.0983,-0.0508&travelmode=driving&waypoints=42.8722,0.0011%7C42.9083,0.1450%7C42.9394,0.3258%7C42.9047,0.3592%7C43.0647,0.1497', 'https://commons.wikimedia.org/wiki/Special:FilePath/Col%20du%20Tourmalet.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Lourdes%20Basilique.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Luz-Saint-Sauveur.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Col%20du%20Tourmalet.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Pic%20du%20Midi%20de%20Bigorre.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Col%20d%27Aspin.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Arreau.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Bagn%C3%A8res-de-Bigorre.jpg"}'::text[], '{"Sanktuárium Lourdes","Luz-Saint-Sauveur","Col du Tourmalet","Pic du Midi de Bigorre","Col d''Aspin","Arreau","Restaurace: Le Jardin des Brouches (Bagnères-de-Bigorre)"}'::text[], '{"FR"}'::text[], false, 3860, 'approved');

  -- Bretaň – Pointe du Raz a poloostrov Crozon
  delete from public.routes where name = 'Bretaň – Pointe du Raz a poloostrov Crozon' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Bretaň – Pointe du Raz a poloostrov Crozon', 'Okruh nejdivočejším koncem Bretaně — krajem Finistère, „koncem světa". Z Quimperu zamíříte přes středověký Locronan na poloostrov Crozon k útesům Pointe de Pen-Hir, pak podél zálivu do rybářského Douarnenez a na západní výspu Francie Pointe du Raz, kde se Atlantik tříští o žulové skály u majáků. Silnice jsou úzké, zvlněné a lemované kamennými zídkami a vřesovišti; provoz mimo červenec a srpen minimální. Nejhezčí je jízda za proměnlivého počasí, kdy se nad oceánem honí mraky — počítejte ale s větrem a přeháňkami v kterémkoli měsíci. Pozor na kluzké rozjeté řasy a písek na pobřežních úsecích.', 'loop', 210, 300, 'medium',
     '[{"lat": 47.9960, "lng": -4.1028, "label": "Start: Quimper"}, {"lat": 48.0981, "lng": -4.2094, "label": "Locronan"}, {"lat": 48.2597, "lng": -4.6272, "label": "Pointe de Pen-Hir"}, {"lat": 48.0922, "lng": -4.3286, "label": "Douarnenez"}, {"lat": 48.0397, "lng": -4.7369, "label": "Pointe du Raz"}, {"lat": 48.0219, "lng": -4.5386, "label": "Audierne"}, {"lat": 47.9960, "lng": -4.1028, "label": "Cíl: Quimper"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=47.9960,-4.1028&destination=47.9960,-4.1028&travelmode=driving&waypoints=48.0981,-4.2094%7C48.2597,-4.6272%7C48.0922,-4.3286%7C48.0397,-4.7369%7C48.0219,-4.5386', 'https://commons.wikimedia.org/wiki/Special:FilePath/Pointe%20du%20Raz.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Locronan.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Locronan.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Pointe%20de%20Pen-Hir.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Douarnenez.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Pointe%20du%20Raz.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Cath%C3%A9drale%20Saint-Corentin%20de%20Quimper.jpg"}'::text[], '{"Locronan","Restaurace: Crêperie Ty Coz (Locronan)","Pointe de Pen-Hir","Douarnenez","Pointe du Raz","Quimper – katedrála sv. Korentina"}'::text[], '{"FR"}'::text[], false, 3870, 'approved');

  -- Normandie – útesy Étretat a Honfleur
  delete from public.routes where name = 'Normandie – útesy Étretat a Honfleur' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Normandie – útesy Étretat a Honfleur', 'Pohodová jízda podél Alabastrového pobřeží Normandie z Fécampu do Deauville, ve stopách impresionistů. Křídové útesy u Étretat s proslulými skalními oblouky patří k nejikoničtějším scenériím Francie a silnice mezi poli lnu a řepky nad nimi jsou příjemně plynulé. Přes elegantní most Pont de Normandie, klenoucí se 60 metrů nad ústím Seiny, dojedete do malířského přístavu Honfleur a zakončíte na promenádě mondénního Deauville. Trasa je nenáročná a krásná od jara do podzimu; nejhezčí světlo na útesech je ráno a za soumraku. Počítejte s větrem od Kanálu a o víkendech s výletním provozem u Étretat, kde parkujte na záchytných parkovištích.', 'poi', 110, 180, 'easy',
     '[{"lat": 49.7581, "lng": 0.3742, "label": "Start: Fécamp"}, {"lat": 49.7069, "lng": 0.2050, "label": "Étretat"}, {"lat": 49.4325, "lng": 0.2747, "label": "Pont de Normandie"}, {"lat": 49.4194, "lng": 0.2331, "label": "Honfleur"}, {"lat": 49.3600, "lng": 0.0750, "label": "Cíl: Deauville"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=49.7581,0.3742&destination=49.3600,0.0750&travelmode=driving&waypoints=49.7069,0.2050%7C49.4325,0.2747%7C49.4194,0.2331', 'https://commons.wikimedia.org/wiki/Special:FilePath/Etretat.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Palais%20B%C3%A9n%C3%A9dictine.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Etretat.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Pont%20de%20Normandie.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Honfleur%20Vieux%20Bassin.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Honfleur%20Vieux%20Bassin.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Deauville.jpg"}'::text[], '{"Fécamp – Palais Bénédictine","Étretat – útesy a oblouk Aval","Pont de Normandie","Honfleur – Vieux Bassin","Restaurace: Le Bréard (Honfleur)","Deauville – Les Planches"}'::text[], '{"FR"}'::text[], false, 3880, 'approved');

  -- Route Napoléon – z Grasse do Grenoblu
  delete from public.routes where name = 'Route Napoléon – z Grasse do Grenoblu' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Route Napoléon – z Grasse do Grenoblu', 'Slavná N85 sleduje cestu, kterou Napoleon v březnu 1815 táhl z Elby na Paříž — a dnes je to jedna z nejlepších motorkářských dálkových silnic Evropy. Z voňavého města parfémů Grasse stoupá přes provensálské vápencové hřebeny ke Castellane, pokračuje levandulovým krajem kolem Digne-les-Bains a pod citadelou v Sisteronu vjíždí do alpského předhůří k Gapu a jezerům u Laffrey. Široké oblouky, kvalitní asfalt a věčné střídání scenérií od olivovníků po alpské štíty dělají z celodenní jízdy zážitek bez jediného nudného kilometru. Ideální období je květen až říjen; v létě se vyhněte přehřátému odpoledni na jihu a víkendovým kolonám u Grenoblu. Orlí siluety na značkách podél cesty připomínají císařův let na sever.', 'poi', 330, 420, 'medium',
     '[{"lat": 43.6589, "lng": 6.9256, "label": "Start: Grasse"}, {"lat": 43.8469, "lng": 6.5128, "label": "Castellane"}, {"lat": 44.0919, "lng": 6.2358, "label": "Digne-les-Bains"}, {"lat": 44.1950, "lng": 5.9433, "label": "Sisteron"}, {"lat": 44.5594, "lng": 6.0786, "label": "Gap"}, {"lat": 45.0197, "lng": 5.7736, "label": "Laffrey"}, {"lat": 45.1885, "lng": 5.7245, "label": "Cíl: Grenoble"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=43.6589,6.9256&destination=45.1885,5.7245&travelmode=driving&waypoints=43.8469,6.5128%7C44.0919,6.2358%7C44.1950,5.9433%7C44.5594,6.0786%7C45.0197,5.7736', 'https://commons.wikimedia.org/wiki/Special:FilePath/Grasse.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Grasse.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Castellane.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Digne-les-Bains.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Sisteron.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Sisteron.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Lac%20de%20Laffrey.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Grenoble.jpg"}'::text[], '{"Grasse – město parfémů","Castellane","Digne-les-Bains","Sisteron – citadela","Restaurace: Les Becs Fins (Sisteron)","Lac de Laffrey","Grenoble – Bastille"}'::text[], '{"FR"}'::text[], false, 3890, 'approved');

  -- Cévennes – Corniche a viadukt Millau
  delete from public.routes where name = 'Cévennes – Corniche a viadukt Millau' and branch_id = v_branch;
  v_route := gen_random_uuid();
     waypoints, geometry, mapy_url, cover_image, images, image_alts, countries, is_active, sort_order, status)
  values (v_route, v_branch, 'Cévennes – Corniche a viadukt Millau', 'Přejezd divokým národním parkem Cévennes po hřebenové Corniche des Cévennes — historické cestě táhnoucí se po rozvodí mezi kaštanovými údolími, kterou proslavil už R. L. Stevenson s oslicí Modestine. Z Anduze stoupáte na korniš s výhledy na moře hřebenů, sjedete do Floraku na okraji vápencových planin a přes větrný vrchol Mont Aigoual (1567 m) pokračujete do Meyrueis a kaňonem řeky Jonte k velkolepému finále — viaduktu Millau, nejvyššímu mostu světa. Silnice jsou úzké, prázdné a nekonečně zatáčkovité; tankujte průběžně, benzinek je tu málo. Nejlepší období je květen až říjen, na podzim kraj hraje barvami kaštanů. Na Aigoualu počítejte s větrem a mlhou i uprostřed léta.', 'poi', 185, 300, 'medium',
     '[{"lat": 44.0536, "lng": 3.9856, "label": "Start: Anduze"}, {"lat": 44.1044, "lng": 3.8858, "label": "Saint-Jean-du-Gard"}, {"lat": 44.2036, "lng": 3.7025, "label": "Corniche des Cévennes"}, {"lat": 44.3242, "lng": 3.5936, "label": "Florac"}, {"lat": 44.1214, "lng": 3.5817, "label": "Mont Aigoual"}, {"lat": 44.1800, "lng": 3.4297, "label": "Meyrueis"}, {"lat": 44.0986, "lng": 3.0783, "label": "Cíl: Millau"}]'::jsonb, null, 'https://www.google.com/maps/dir/?api=1&origin=44.0536,3.9856&destination=44.0986,3.0783&travelmode=driving&waypoints=44.1044,3.8858%7C44.2036,3.7025%7C44.3242,3.5936%7C44.1214,3.5817%7C44.1800,3.4297', 'https://commons.wikimedia.org/wiki/Special:FilePath/ViaducdeMillau.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Anduze.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Corniche%20des%20C%C3%A9vennes.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Florac.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Florac.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Mont%20Aigoual.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/Meyrueis.jpg","https://commons.wikimedia.org/wiki/Special:FilePath/ViaducdeMillau.jpg"}'::text[], '{"Anduze – brána Cévenn","Corniche des Cévennes","Florac","Restaurace: L''Adonis (Florac)","Mont Aigoual","Meyrueis","Viaduc de Millau"}'::text[], '{"FR"}'::text[], false, 3900, 'approved');

