  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Lac Blanc', 'Ledovcové jezero v žulovém kotli pod hřebenem Vogéz, obklopené skalami a lesem. Silnice k němu stoupá dlouhou sérií serpentin od Orbey a nahoře na vás čeká parkoviště přímo u břehu i občerstvení. Skvělé místo na první fotopauzu před najetím na hřebenovku.', 48.1367, 7.0908, 'https://commons.wikimedia.org/wiki/Special:FilePath/Lac%20Blanc%20Vosges.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Lac%20Blanc%20Vosges.jpg"}'::text[], 0),
    (v_route, 'Col de la Schlucht', 'Nejznámější vogézské sedlo (1139 m) na hranici Alsaska a Lotrinska, křižovatka hřebenové Route des Crêtes. Nedávno zrekonstruovaný areál nabízí kavárny a výhledy do údolí Munsteru. Odtud pokračuje hřebenovka na jih po jedné z nejplynulejších silnic v pohoří.', 48.0633, 7.0225, 'https://commons.wikimedia.org/wiki/Special:FilePath/Col%20de%20la%20Schlucht.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Col%20de%20la%20Schlucht.jpg"}'::text[], 1),
    (v_route, 'Hohneck', 'Třetí nejvyšší vrchol Vogéz (1363 m) s odbočkou přímo z hřebenovky až téměř na vrchol. Kruhový rozhled zabírá kary s jezírky, pastviny s krávami vogézského plemene i celý hřeben pohoří. Za jasného dne jsou vidět Alpy včetně Mont Blanku.', 48.0403, 7.0161, 'https://commons.wikimedia.org/wiki/Special:FilePath/Le%20Hohneck.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Le%20Hohneck.jpg"}'::text[], 2),
    (v_route, 'Grand Ballon', 'Nejvyšší hora Vogéz (1424 m) s charakteristickou radarovou koulí na vrcholu. Silnice se přes sedlo pod vrcholem přehoupne v dlouhých zatáčkách s výhledy na rýnskou nížinu, Schwarzwald a za dobré viditelnosti i alpské štíty. U horského hotelu se dá pohodlně zastavit na kávu.', 47.9011, 7.0839, 'https://commons.wikimedia.org/wiki/Special:FilePath/Grand%20Ballon.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Grand%20Ballon.jpg"}'::text[], 3),
    (v_route, 'Hartmannswillerkopf (Vieil Armand)', 'Národní památník první světové války na kopci, o který se v letech 1915–1916 sváděly krvavé boje mezi Francií a Německem. Zachovalé zákopy, krypta a hřbitov s tisíci kříži jsou působivou pietní zastávkou přímo u sjezdu z hřebenovky. Vstup do zákopového areálu je volný.', 47.8558, 7.1594, 'https://commons.wikimedia.org/wiki/Special:FilePath/Hartmannswillerkopf.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Hartmannswillerkopf.jpg"}'::text[], 4),
    (v_route, 'Restaurace: Hôtel Verte Vallée (Munster)', 'Zavedená hotelová restaurace v zeleném údolí Munsteru s poctivou alsaskou kuchyní — nechybí místní sýr munster, baeckeoffe ani ryby z horských potoků. Hosté chválí kvalitu jídla i klidnou zahradu, ideální na závěrečnou večeři po hřebenech. Rezervace se o víkendech vyplatí.', 48.0406, 7.1390, 'https://commons.wikimedia.org/wiki/Special:FilePath/Munster%20(Haut-Rhin).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Munster%20(Haut-Rhin).jpg"}'::text[], 5);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Eguisheim', 'Vesnice postavená v soustředných kruzích kolem hradu, pravidelně volená mezi nejkrásnější vesnice Francie. Hrázděné domy obsypané muškáty a vinné sklípky lákají k první degustační zastávce (pro jezdce samozřejmě jen ochutnávka nealko moštu). Motorku zaparkujete u hradeb a centrum projdete pěšky za půl hodiny.', 48.0428, 7.3062, 'https://commons.wikimedia.org/wiki/Special:FilePath/Eguisheim.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Eguisheim.jpg"}'::text[], 0),
    (v_route, 'Kaysersberg', 'Rodiště Alberta Schweitzera s kamenným opevněným mostem přes říčku Weiss a zříceninou hradu nad vinicemi. Z hradní věže je nejhezčí výhled na moře vinic celé stezky. Městečko bylo vyhlášeno nejoblíbenější vesnicí Francouzů.', 48.1392, 7.2617, 'https://commons.wikimedia.org/wiki/Special:FilePath/Kaysersberg.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Kaysersberg.jpg"}'::text[], 1),
    (v_route, 'Riquewihr', 'Snad nejfotografovanější městečko Alsaska, obehnané hradbami a prakticky nezměněné od 16. století. Barevné hrázděné domy v hlavní ulici prý inspirovaly kulisy pohádky Kráska a zvíře. Uvnitř hradeb se nejezdí, parkoviště je hned za branou.', 48.1667, 7.2986, 'https://commons.wikimedia.org/wiki/Special:FilePath/Riquewihr.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Riquewihr.jpg"}'::text[], 2),
    (v_route, 'Restaurace: La Table du Gourmet (Riquewihr)', 'Michelinskou hvězdou oceněná restaurace šéfkuchaře Jeana-Luca Brendela v červeném hrázděném domě z roku 1554. Moderní alsaská kuchyně staví na zelenině a bylinkách z vlastní zahrady; degustační menu patří k zážitkům celé trasy. Na oběd je nutná rezervace, levnější alternativou jsou okolní winstuby.', 48.1668, 7.2984, 'https://commons.wikimedia.org/wiki/Special:FilePath/Riquewihr.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Riquewihr.jpg"}'::text[], 3),
    (v_route, 'Ribeauvillé', 'Město tří hradů — nad vinicemi se tyčí zříceniny Saint-Ulrich, Girsberg a Haut-Ribeaupierre. Dlouhé náměstí lemují renesanční kašny a domy vinařů, v září tu probíhá slavný festival pištců. Příjemná zastávka na kávu před stoupáním k Haut-Kœnigsbourgu.', 48.1953, 7.3196, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ribeauvill%C3%A9.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ribeauvill%C3%A9.jpg"}'::text[], 4),
    (v_route, 'Château du Haut-Kœnigsbourg', 'Monumentální hrad na skalním ostrohu 757 m nad rýnskou nížinou, počátkem 20. století velkolepě obnovený císařem Vilémem II. Serpentiny k hradu jsou nejzábavnějším úsekem celé trasy a z hradeb dohlédnete přes Rýn až ke Schwarzwaldu. V hlavní sezóně dorazte brzy ráno, parkoviště se rychle plní.', 48.2494, 7.3444, 'https://commons.wikimedia.org/wiki/Special:FilePath/Haut-Koenigsbourg.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Haut-Koenigsbourg.jpg"}'::text[], 5),
    (v_route, 'Colmar – Petite Venise', 'Čtvrť Malé Benátky v historickém centru Colmaru, kde se hrázděné domy zrcadlí v kanálech říčky Lauch. Ideální místo na závěrečnou procházku a večeři po okruhu; staré město je z velké části pěší zóna. Colmar je zároveň hlavním městem alsaského vína a sídlem slavného Isenheimského oltáře.', 48.0733, 7.3585, 'https://commons.wikimedia.org/wiki/Special:FilePath/Colmar%20Petite%20Venise.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Colmar%20Petite%20Venise.jpg"}'::text[], 6);
  insert into public.routes
