  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Mont Ventoux', 'Obr Provence — osamělá hora s holým vápencovým vrcholem, který z dálky vypadá jako zasněžený. Stoupání z Bédoin má 21 km a přes 1600 výškových metrů, nahoře čeká meteorologická věž, památník cyklisty Toma Simpsona a výhled od Alp po Středozemní moře. Při silném mistralu bývá vrcholová silnice uzavřená.', 44.1741, 5.2786, 'https://commons.wikimedia.org/wiki/Special:FilePath/MontVentoux.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/MontVentoux.jpg"}'::text[], 0),
    (v_route, 'Sault – levandulová pole', 'Městečko na skalní terase nad náhorní plošinou, která se na přelomu června a července změní ve fialový oceán levandule. Sjezd z Ventoux přes Sault patří k nejvoňavějším kilometrům Francie. V místních obchůdcích koupíte levandulový med a nugát.', 44.0894, 5.4103, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sault%20Vaucluse.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Sault%20Vaucluse.jpg"}'::text[], 1),
    (v_route, 'Roussillon – okrové skály', 'Vesnice vystavěná na největším ložisku okru v Evropě — domy i skály kolem hrají všemi odstíny červené, oranžové a žluté. Krátká procházka Sentier des Ocres vede bývalými lomy jako z jiné planety. Patří mezi oficiálně nejkrásnější vesnice Francie.', 43.9028, 5.2928, 'https://commons.wikimedia.org/wiki/Special:FilePath/Roussillon%20Vaucluse.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Roussillon%20Vaucluse.jpg"}'::text[], 2),
    (v_route, 'Gordes', 'Ikona Luberonu — kamenná vesnice nalepená na skalním srázu, kterou proslavily filmy i fotografie z vyhlídky na příjezdové silnici. Renesanční zámek a bludiště kamenných uliček stojí za hodinovou zastávku. Vyhlídka bývá v poledne obsypaná, ráno ji máte pro sebe.', 43.9114, 5.2003, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gordes.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Gordes.jpg"}'::text[], 3),
    (v_route, 'Abbaye de Sénanque', 'Cisterciácké opatství z 12. století ukryté v úzkém údolí pod Gordes, před kterým kvetou nejfotografovanější levandulové záhony světa. Mniši tu dodnes žijí a hospodaří; kostel je přístupný a v obchůdku prodávají vlastní levandulové produkty. Úzká přístupová silnice vyžaduje ohleduplnost k protijedoucím.', 43.9286, 5.1869, 'https://commons.wikimedia.org/wiki/Special:FilePath/Abbaye%20de%20S%C3%A9nanque.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Abbaye%20de%20S%C3%A9nanque.jpg"}'::text[], 4),
    (v_route, 'Fontaine-de-Vaucluse', 'Nejmohutnější pramen Francie — smaragdové jezírko pod 230 m vysokou skalní stěnou, ze kterého vyvěrá řeka Sorgue. Na jaře chrlí až 90 kubíků vody za sekundu a údolí hučí jako vodopád. Podél řeky vede stinná promenáda s kavárnami, ideální na ochlazení v horkém dni.', 43.9231, 5.1272, 'https://commons.wikimedia.org/wiki/Special:FilePath/Fontaine-de-Vaucluse.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Fontaine-de-Vaucluse.jpg"}'::text[], 5),
    (v_route, 'Restaurace: Chez Serge (Carpentras)', 'Oblíbená restaurace v historickém centru Carpentras, která spojuje provensálskou kuchyni s vynikající prací s lanýži a pizzou z pece na dřevo. Hosté dlouhodobě chválí poměr ceny a kvality i výběr místních vín. Skvělá tečka za celodenním okruhem po Provence.', 44.0546, 5.0478, 'https://commons.wikimedia.org/wiki/Special:FilePath/Carpentras.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Carpentras.jpg"}'::text[], 6);
  insert into public.routes
