  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Pont d''Arc', 'Přírodní skalní oblouk vysoký 54 metrů, kterým protéká řeka Ardèche — symbol celého kraje a startovní brána kaňonu. Pláže pod obloukem lákají ke koupání, nad řekou křižují kánoe. Kousek odtud je replika jeskyně Chauvet s nejstaršími malbami lidstva.', 44.3803, 4.4122, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pont%20d%27Arc.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Pont%20d%27Arc.jpg"}'::text[], 0),
    (v_route, 'Belvédère de la Madeleine (Gorges de l''Ardèche)', 'Nejslavnější z vyhlídek na korniši D290 — řeka se tu 300 metrů pod vámi stáčí kolem skalní jehly Cathédrale. Vyhlídková silnice mezi Vallon a Saint-Martin-d''Ardèche nabízí tucet podobných balkonů, Madeleine je z nich nejvzdušnější. Ideální místo na fotku celé soutěsky.', 44.3390, 4.5160, 'https://commons.wikimedia.org/wiki/Special:FilePath/Gorges%20de%20l%27Ard%C3%A8che.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Gorges%20de%20l%27Ard%C3%A8che.jpg"}'::text[], 1),
    (v_route, 'Aven d''Orgnac', 'Jedna z největších zpřístupněných propastí Evropy — výtah vás sveze 121 metrů pod zem do sálů s krápníky vysokými přes 10 metrů. Prohlídka trvá hodinu a v podzemí je stálých 12 °C, což v létě přijde vhod. Součástí areálu je moderní muzeum pravěku.', 44.3186, 4.4108, 'https://commons.wikimedia.org/wiki/Special:FilePath/Aven%20d%27Orgnac.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Aven%20d%27Orgnac.jpg"}'::text[], 2),
    (v_route, 'Labeaume', 'Kamenná vesnice vklíněná mezi skály nad říčkou Beaume, s náměstíčkem pod platany a domy srostlými s vápencovou stěnou. Od řeky se dá vyjít na vyhlídku nad meandrem. Klidnější alternativa přeplněných slavnějších sousedů.', 44.4703, 4.3417, 'https://commons.wikimedia.org/wiki/Special:FilePath/Labeaume.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Labeaume.jpg"}'::text[], 3),
    (v_route, 'Balazuc', 'Oficiálně jedna z nejkrásnějších vesnic Francie — kamenné domy šplhají po útesu nad řekou Ardèche a silnice pod vesnicí přechází řeku úzkým mostem s krásným výhledem. Románský kostelík a uličky sotva na šířku ramen stojí za procházku. V létě funguje pláž přímo pod vsí.', 44.5083, 4.3711, 'https://commons.wikimedia.org/wiki/Special:FilePath/Balazuc.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Balazuc.jpg"}'::text[], 4),
    (v_route, 'Vogüé', 'Vesnice pod obloukovitou skalní stěnou, které vévodí zámek rodu Vogüé s visutými zahradami. Domy s podloubími lemují břeh Ardèche a od mostu je jedno z nejmalebnějších panoramat kraje. Dobrá kávová zastávka před návratem do Vallon.', 44.5386, 4.4144, 'https://commons.wikimedia.org/wiki/Special:FilePath/Vog%C3%BC%C3%A9.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Vog%C3%BC%C3%A9.jpg"}'::text[], 5);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Puy de Dôme', 'Nejvyšší sopka řetězu Chaîne des Puys (1465 m) s římským chrámem boha Merkura na vrcholu. Nahoru vás vyveze zubačka Panoramique des Dômes — z vrcholu přehlédnete všech osmdesát sopek najednou. Symbol Auvergne a jeden z nejnavštěvovanějších vrcholů Francie.', 45.7722, 2.9644, 'https://commons.wikimedia.org/wiki/Special:FilePath/Puy%20de%20D%C3%B4me.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Puy%20de%20D%C3%B4me.jpg"}'::text[], 0),
    (v_route, 'Puy de Pariou', 'Učebnicová sopka s dokonale kruhovým kráterem hlubokým 97 metrů, známá z reklam na minerálku Volvic. Z parkoviště u silnice D941 se dá vyjít na hranu kráteru za necelou hodinu. Kužel porostlý trávou je nejfotogeničtější z celého řetězu.', 45.7961, 2.9700, 'https://commons.wikimedia.org/wiki/Special:FilePath/Puy%20Pariou.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Puy%20Pariou.jpg"}'::text[], 1),
    (v_route, 'Lac de Guéry', 'Nejvýše položené jezero Auvergne (1250 m) vzniklé přehrazením údolí lávovým proudem, s výhledem na skalní věže Tuilière a Sanadoire. Silnice přes Col de Guéry patří k nejhezčím úsekům okruhu. V zimě se tu jako na jediném místě Francie loví ryby dírou v ledu.', 45.6083, 2.8092, 'https://commons.wikimedia.org/wiki/Special:FilePath/Lac%20de%20Gu%C3%A9ry.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Lac%20de%20Gu%C3%A9ry.jpg"}'::text[], 2),
    (v_route, 'Puy de Sancy', 'Nejvyšší hora Francouzského středohoří (1885 m), rozeklaný pozůstatek obřího stratovulkánu nad lázněmi Le Mont-Dore. Lanovka a schody vás dostanou na vrcholový hřeben s výhledem přes půl Francie. Pod horou pramení Dordogne.', 45.5286, 2.8139, 'https://commons.wikimedia.org/wiki/Special:FilePath/Puy%20de%20Sancy.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Puy%20de%20Sancy.jpg"}'::text[], 3),
    (v_route, 'Restaurace: Le Bougnat (Le Mont-Dore)', 'Tradiční auvergnská hospoda v centru lázeňského Le Mont-Dore, kde servírují krajové speciality jako truffade, aligot a potée auvergnate. Poctivé porce, místní sýry saint-nectaire a přátelská atmosféra z ní dělají ideální obědovou zastávku uprostřed okruhu. V sezóně počítejte s čekáním.', 45.5714, 2.8083, 'https://commons.wikimedia.org/wiki/Special:FilePath/Le%20Mont-Dore.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Le%20Mont-Dore.jpg"}'::text[], 4),
    (v_route, 'Lac Pavin', 'Dokonale kruhové kráterové jezero o průměru 800 metrů a hloubce 92 metrů, nejmladší sopečný útvar Francie (vybuchl před pouhými 7000 lety). Temně modrá hladina obklopená lesem působí až tajemně — podle pověstí je na dně potopené město. Kolem jezera vede pohodlná stezka.', 45.4956, 2.8878, 'https://commons.wikimedia.org/wiki/Special:FilePath/Lac%20Pavin.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Lac%20Pavin.jpg"}'::text[], 5),
    (v_route, 'Besse-et-Saint-Anastaise', 'Středověké městečko postavené z černé lávy, s branami, věžemi a kupeckými domy z 15. století. Je centrem výroby sýra saint-nectaire — v krámcích ho koupíte přímo od farmářů. Tmavý kámen dává uličkám nezaměnitelnou atmosféru.', 45.5178, 2.9331, 'https://commons.wikimedia.org/wiki/Special:FilePath/Besse-et-Saint-Anastaise.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Besse-et-Saint-Anastaise.jpg"}'::text[], 6);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Sanktuárium Lourdes', 'Nejnavštěvovanější poutní místo Francie s bazilikou Růžence nad jeskyní zjevení Panny Marie. I bez náboženského rozměru stojí monumentální areál nad řekou Gave de Pau za ranní procházku, než vyrazíte do hor. Večer tu probíhají působivá světelná procesí.', 43.0975, -0.0583, 'https://commons.wikimedia.org/wiki/Special:FilePath/Lourdes%20Basilique.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Lourdes%20Basilique.jpg"}'::text[], 0),
    (v_route, 'Luz-Saint-Sauveur', 'Horské městečko na soutoku dvou údolí s opevněným templářským kostelem a Napoleonovým mostem klenoucím se 65 metrů nad soutěskou. Poslední zastávka na kávu a palivo před stoupáním na Tourmalet. V sezóně tu žije čilý horský ruch.', 42.8722, 0.0011, 'https://commons.wikimedia.org/wiki/Special:FilePath/Luz-Saint-Sauveur.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Luz-Saint-Sauveur.jpg"}'::text[], 1),
    (v_route, 'Col du Tourmalet', 'Nejslavnější průsmyk Tour de France (2115 m), zdolávaný závodem častěji než kterýkoli jiný. Na vrcholu stojí stříbrná socha Octave Lapize — Géant du Tourmalet — a panorama holých štítů střeží observatoř na Pic du Midi. Serpentiny z obou stran patří k nejlepším motorkářským stoupáním Pyrenejí.', 42.9083, 0.1450, 'https://commons.wikimedia.org/wiki/Special:FilePath/Col%20du%20Tourmalet.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Col%20du%20Tourmalet.jpg"}'::text[], 2),
    (v_route, 'Pic du Midi de Bigorre', 'Hvězdárna na vrcholu ve výšce 2877 m, kam z lyžařské La Mongie jezdí kabinová lanovka. Z teras je závratný výhled na tři sta kilometrů pyrenejského hřebene — za jasného dne jeden z nejlepších vyhlídkových bodů Francie. Nahoře funguje muzeum i restaurace.', 42.9369, 0.1411, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pic%20du%20Midi%20de%20Bigorre.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Pic%20du%20Midi%20de%20Bigorre.jpg"}'::text[], 3),
    (v_route, 'Col d''Aspin', 'Zelený protipól drsného Tourmaletu — sedlo v 1490 m obklopené pastvinami s výhledem na štít Arbizon. Krávy tu leží klidně i uprostřed silnice, což dodává průsmyku pohodovou atmosféru. Sjezd do Arreau je plynulý tanec dlouhých zatáček mezi lesy.', 42.9394, 0.3258, 'https://commons.wikimedia.org/wiki/Special:FilePath/Col%20d%27Aspin.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Col%20d%27Aspin.jpg"}'::text[], 4),
    (v_route, 'Arreau', 'Půvabné kamenné městečko na soutoku dvou řek, křižovatka pyrenejských údolí s hrázděnou tržnicí a břidlicovými střechami. Ideální místo na oběd nebo zmrzlinu mezi průsmyky. Odtud se trasa stáčí zpět na sever podél řeky Neste.', 42.9047, 0.3592, 'https://commons.wikimedia.org/wiki/Special:FilePath/Arreau.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Arreau.jpg"}'::text[], 5),
    (v_route, 'Restaurace: Le Jardin des Brouches (Bagnères-de-Bigorre)', 'Vyhlášená restaurace v lázeňském Bagnères-de-Bigorre s moderní pyrenejskou kuchyní z lokálních surovin — jehněčí z okolních pastvin, horské sýry a sezónní zelenina. Hosté dlouhodobě chválí přívětivou obsluhu i zahradní terasu. Skvělé zakončení vysokohorského dne.', 43.0647, 0.1497, 'https://commons.wikimedia.org/wiki/Special:FilePath/Bagn%C3%A8res-de-Bigorre.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Bagn%C3%A8res-de-Bigorre.jpg"}'::text[], 6);
