  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Locronan', 'Dokonale zachované středověké městečko z žulových domů kolem kostela sv. Ronana, kde se točily filmy jako Tess. Auta ani motorky do centra nesmí, parkoviště je hned za vsí. Jedna z oficiálně nejkrásnějších vesnic Francie a povinná zastávka trasy.', 48.0981, -4.2094, 'https://commons.wikimedia.org/wiki/Special:FilePath/Locronan.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Locronan.jpg"}'::text[], 0),
    (v_route, 'Restaurace: Crêperie Ty Coz (Locronan)', 'Tradiční bretaňská creperie v kamenném domě přímo v historickém jádru Locronanu. Pohankové galettes s místními surovinami a sladké palačinky s karamelem ze slaného másla patří k nejlépe hodnoceným v kraji. K tomu si dejte jablečný cidre — pro jezdce samozřejmě až večer, nebo sáhněte po nealko moštu.', 48.0980, -4.2092, 'https://commons.wikimedia.org/wiki/Special:FilePath/Locronan.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Locronan.jpg"}'::text[], 1),
    (v_route, 'Pointe de Pen-Hir', 'Nejefektnější mys poloostrova Crozon se 70metrovými útesy a řadou skalisek Tas de Pois trčících z oceánu. Nad útesy stojí mohutný kříž — památník bretaňského odboje. Kolem vedou stezky vřesovištěm s výhledy, které berou dech.', 48.2597, -4.6272, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pointe%20de%20Pen-Hir.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Pointe%20de%20Pen-Hir.jpg"}'::text[], 2),
    (v_route, 'Douarnenez', 'Rybářské město proslulé sardinkami a přístavem Port-Rhu s muzejními loděmi. Podle legendy leží v zálivu potopené město Ys. Nábřeží s barevnými domky a konzervárenskými krámky je příjemné místo na protažení nohou.', 48.0922, -4.3286, 'https://commons.wikimedia.org/wiki/Special:FilePath/Douarnenez.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Douarnenez.jpg"}'::text[], 3),
    (v_route, 'Pointe du Raz', 'Nejzápadnější dramatický výběžek Bretaně — žulové útesy vysoké 72 metrů, o které se tříští atlantický příboj, a výhled na maják Vieille v divoké úžině Raz de Sein. Od parkoviště k mysu se jde pěšky asi 20 minut vřesovištěm. Za bouřlivého počasí nezapomenutelné divadlo živlů.', 48.0397, -4.7369, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pointe%20du%20Raz.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Pointe%20du%20Raz.jpg"}'::text[], 4),
    (v_route, 'Quimper – katedrála sv. Korentina', 'Hlavní město tradiční Cornouaille s gotickou katedrálou, jejíž dvě věže dominují hrázděnému starému městu na řece Odet. Město proslulo ručně malovanou fajánsí, kterou tu vyrábějí přes 300 let. Ideální start i cíl okruhu s dobrou nabídkou ubytování.', 47.9960, -4.1028, 'https://commons.wikimedia.org/wiki/Special:FilePath/Cath%C3%A9drale%20Saint-Corentin%20de%20Quimper.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Cath%C3%A9drale%20Saint-Corentin%20de%20Quimper.jpg"}'::text[], 5);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Fécamp – Palais Bénédictine', 'Extravagantní novogotický palác, kde se dodnes vyrábí bylinný likér Bénédictine z 27 bylin a koření. Prohlídka provede palácem, muzeem i destilerií; degustaci si jezdec schová na večer. Fécamp je zároveň starý rybářský přístav pod nejvyššími útesy Alabastrového pobřeží.', 49.7581, 0.3742, 'https://commons.wikimedia.org/wiki/Special:FilePath/Palais%20B%C3%A9n%C3%A9dictine.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Palais%20B%C3%A9n%C3%A9dictine.jpg"}'::text[], 0),
    (v_route, 'Étretat – útesy a oblouk Aval', 'Křídové útesy s obloukem Porte d''Aval a osamělou jehlou Aiguille, které maloval Monet i Courbet. Nejlepší výhled je z útesu Amont u kapličky námořníků, kam se dá vyjít pěšky z města. Ráno a večer patří scenérie k nejfotogeničtějším místům celé Francie.', 49.7069, 0.2050, 'https://commons.wikimedia.org/wiki/Special:FilePath/Etretat.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Etretat.jpg"}'::text[], 1),
    (v_route, 'Pont de Normandie', 'Elegantní zavěšený most přes ústí Seiny s rozpětím 856 metrů, při otevření v roce 1995 nejdelší svého druhu na světě. Přejezd po mostě 60 metrů nad řekou je zážitek sám o sobě — při bočním větru držte pevně řídítka. Mýtné pro motocykly je snížené.', 49.4325, 0.2747, 'https://commons.wikimedia.org/wiki/Special:FilePath/Pont%20de%20Normandie.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Pont%20de%20Normandie.jpg"}'::text[], 2),
    (v_route, 'Honfleur – Vieux Bassin', 'Starý přístavní bazén lemovaný úzkými břidlicovými domy, jeden z nejmalebnějších přístavů Evropy a kolébka impresionismu. Za návštěvu stojí dřevěný kostel sv. Kateřiny stavěný loďaři jako obrácený trup lodi. Nábřežní kavárny jsou ideální na odpolední pauzu.', 49.4194, 0.2331, 'https://commons.wikimedia.org/wiki/Special:FilePath/Honfleur%20Vieux%20Bassin.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Honfleur%20Vieux%20Bassin.jpg"}'::text[], 3),
    (v_route, 'Restaurace: Le Bréard (Honfleur)', 'Elegantní gastronomická restaurace v dlážděné uličce kousek od kostela sv. Kateřiny. Šéfkuchař staví na normandských surovinách — mušle svatého Jakuba, ryby z Kanálu a sýry z okolních farem — v moderním podání. Patří k nejlépe hodnoceným podnikům v Honfleur, rezervace nutná.', 49.4189, 0.2336, 'https://commons.wikimedia.org/wiki/Special:FilePath/Honfleur%20Vieux%20Bassin.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Honfleur%20Vieux%20Bassin.jpg"}'::text[], 4),
    (v_route, 'Deauville – Les Planches', 'Mondénní přímořské letovisko s proslulou prkennou promenádou Les Planches, plážovými slunečníky a kabinkami se jmény filmových hvězd amerického festivalu. Belle époque vily, kasino a dostihová dráha dotvářejí atmosféru „pařížského 21. obvodu". Stylová tečka za projížďkou Normandií.', 49.3600, 0.0750, 'https://commons.wikimedia.org/wiki/Special:FilePath/Deauville.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Deauville.jpg"}'::text[], 5);
  insert into public.routes
    (id, branch_id, name, description, route_type, distance_km, duration_min, difficulty,
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Grasse – město parfémů', 'Světová metropole parfémů na svazích nad Azurovým pobřežím, kde Napoleonova cesta na sever začíná. Historické parfumerie Fragonard a Molinard nabízejí prohlídky zdarma a staré město voní jasmínem. Než vyrazíte, projděte si terasy s výhledem až k moři.', 43.6589, 6.9256, 'https://commons.wikimedia.org/wiki/Special:FilePath/Grasse.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Grasse.jpg"}'::text[], 0),
    (v_route, 'Castellane', 'Městečko sevřené horami, nad kterým na 184 metrů vysoké skále stojí kaple Notre-Dame du Roc. Náměstíčko s platany je tradiční motorkářská zastávka na kávu — sjíždějí se sem jezdci z celé Evropy. Napoleon tudy prošel 3. března 1815, jak připomíná deska na radnici.', 43.8469, 6.5128, 'https://commons.wikimedia.org/wiki/Special:FilePath/Castellane.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Castellane.jpg"}'::text[], 1),
    (v_route, 'Digne-les-Bains', 'Lázeňské město uprostřed levandulových polí a geologicky nejbohatšího území Francie — okolní geopark UNESCO chrání stěny s tisíci zkamenělými amonity. Každý srpen tu vrcholí levandulové slavnosti Corso de la Lavande. Příjemná zastávka na oběd ve stínu platanů.', 44.0919, 6.2358, 'https://commons.wikimedia.org/wiki/Special:FilePath/Digne-les-Bains.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Digne-les-Bains.jpg"}'::text[], 2),
    (v_route, 'Sisteron – citadela', 'Brána Provence — mohutná citadela na skále nad průrvou řeky Durance, proti níž se zvedá zvrásněný masiv Rocher de la Baume. Průjezd soutěskou pod hradbami je jedním z nejefektnějších momentů celé N85. Z hradeb citadely přehlédnete půlku trasy.', 44.1950, 5.9433, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sisteron.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Sisteron.jpg"}'::text[], 3),
    (v_route, 'Restaurace: Les Becs Fins (Sisteron)', 'Tradiční rodinná restaurace v centru Sisteronu proslulá místní specialitou — jehněčím ze sisteronských pastvin, které patří k nejlepším ve Francii. Poctivá provensálská kuchyně a rozumné ceny z ní dělají ideální obědovou zastávku v půli Route Napoléon. V sezóně si rezervujte stůl na terase.', 44.1948, 5.9435, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sisteron.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Sisteron.jpg"}'::text[], 4),
    (v_route, 'Lac de Laffrey', 'Největší ze čtyř jezer na náhorní plošině Matheysine, kde se 7. března 1815 odehrálo slavné setkání: Napoleon se tu postavil vojsku vyslanému ho zatknout — a vojáci přeběhli k němu. Událost připomíná jezdecká socha císaře na Prairie de la Rencontre nad jezerem. Chladná voda jezera láká v létě ke koupání.', 45.0264, 5.7758, 'https://commons.wikimedia.org/wiki/Special:FilePath/Lac%20de%20Laffrey.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Lac%20de%20Laffrey.jpg"}'::text[], 5),
    (v_route, 'Grenoble – Bastille', 'Alpská metropole obklopená třemi horskými masivy, kde Route Napoléon končí. Bublinové lanovky vyvezou z centra na pevnost Bastille s výhledem na město a za jasného dne až na Mont Blanc. Staré město s kavárnami je příjemným místem na závěrečnou večeři.', 45.1885, 5.7245, 'https://commons.wikimedia.org/wiki/Special:FilePath/Grenoble.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Grenoble.jpg"}'::text[], 6);
  insert into public.routes
