  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order) values
    (v_route, 'Anduze – brána Cévenn', 'Městečko sevřené skalní branou řeky Gardon, odkud začíná stoupání do hor. Za návštěvu stojí obří bambusový park Bambouseraie, největší v Evropě, a keramické trhy proslulé vázami z Anduze. Poslední pořádné zásobovací místo před horami.', 44.0536, 3.9856, 'https://commons.wikimedia.org/wiki/Special:FilePath/Anduze.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Anduze.jpg"}'::text[], 0),
    (v_route, 'Corniche des Cévennes', 'Hřebenová silnice D9 mezi Saint-Jean-du-Gard a Florakem, vedoucí desítky kilometrů po rozvodí s výhledy do kaštanových údolí na obě strany. Vinula se tudy královská cesta z dob válek s kamizardy a dnes je to motorkářský klenot — prázdná, plynulá, s panoramaty na každém kilometru. Zastavte na sedle Col des Faïsses.', 44.2036, 3.7025, 'https://commons.wikimedia.org/wiki/Special:FilePath/Corniche%20des%20C%C3%A9vennes.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Corniche%20des%20C%C3%A9vennes.jpg"}'::text[], 1),
    (v_route, 'Florac', 'Městečko na soutoku tří řek pod vápencovou stěnou planiny Causse Méjean, sídlo správy národního parku Cévennes. Zámeček s expozicí parku a uličky podél kanálů stojí za krátkou procházku. Strategické místo na oběd uprostřed přejezdu.', 44.3242, 3.5936, 'https://commons.wikimedia.org/wiki/Special:FilePath/Florac.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Florac.jpg"}'::text[], 2),
    (v_route, 'Restaurace: L''Adonis (Florac)', 'Restaurace rodinného hotelu Gorges du Tarn ve Floraku, oceňovaná za moderní kuchyni z lokálních surovin Lozère — pstruzi z horských řek, jehněčí z planin a cévennská cibule. Slunná terasa a milá obsluha z ní dělají nejlepší obědovou zastávku trasy. Mimo sezónu ověřte otevírací dobu.', 44.3245, 3.5931, 'https://commons.wikimedia.org/wiki/Special:FilePath/Florac.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Florac.jpg"}'::text[], 3),
    (v_route, 'Mont Aigoual', 'Nejvyšší hora jižních Cévenn (1567 m) s poslední obsazenou horskou meteorologickou observatoří Francie na vrcholu. Za jasného dne dohlédnete od Alp přes Středozemní moře až k Pyrenejím — a vane tu vítr, který láme rekordy. Silnice na vrchol je plynulá a vede až k observatoři s muzeem počasí.', 44.1214, 3.5817, 'https://commons.wikimedia.org/wiki/Special:FilePath/Mont%20Aigoual.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Mont%20Aigoual.jpg"}'::text[], 4),
    (v_route, 'Meyrueis', 'Horské městečko na dně kaňonu řeky Jonte, ideální základna mezi planinami Causses a Cévennami. Odtud vede sjezd soutěskou Gorges de la Jonte, nad kterou krouží supi bělohlaví z nedaleké rezervace. Náměstíčko s kavárnami u řeky je stvořené na poslední kávu před Millau.', 44.1800, 3.4297, 'https://commons.wikimedia.org/wiki/Special:FilePath/Meyrueis.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Meyrueis.jpg"}'::text[], 5),
    (v_route, 'Viaduc de Millau', 'Nejvyšší most světa — mistrovské dílo Normana Fostera a Michela Virlogeuxe, jehož pylony ční 343 metrů nad údolím Tarnu. Nejlepší pohled je z vyhlídky u informačního centra pod mostem nebo z městečka Peyre na břehu Tarnu. Velkolepá tečka za přejezdem Cévenn.', 44.0789, 3.0225, 'https://commons.wikimedia.org/wiki/Special:FilePath/ViaducdeMillau.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/ViaducdeMillau.jpg"}'::text[], 6);
